export interface ConnectorConfig {
  /** Linear API key (Bearer token). Typically from LINEAR_API_KEY env var. */
  linearApiKey: string
  /** Linear team identifier (slug or UUID). Defaults to 'triage'. */
  teamId?: string
  /** Injected fetch for testing. Uses global fetch when omitted. */
  fetch?: typeof fetch
}

export interface GitHubIssueLabelEvent {
  action: string
  issue: {
    title: string
    body: string | null
    labels: Array<{ name: string }>
  }
  label: {
    name: string
  }
}

export interface HandleResult {
  linearIssueId: string
  linearIssueIdentifier: string
}

async function graphqlRequest(
  fetch: typeof fetch,
  apiKey: string,
  query: string,
  variables: Record<string, unknown>
): Promise<unknown> {
  const response = await fetch('https://api.linear.app/graphql', {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      Authorization: `Bearer ${apiKey}`,
    },
    body: JSON.stringify({ query, variables }),
  })

  if (!response.ok) {
    const text = await response.text().catch(() => '')
    throw new Error(`Linear API error: ${response.status} ${response.statusText} at POST https://api.linear.app/graphql - ${text}`)
  }

  return response.json()
}

export async function handle(
  payload: GitHubIssueLabelEvent,
  config: ConnectorConfig
): Promise<HandleResult> {
  const fetchImpl = config.fetch ?? fetch

  // Validate required fields
  if (!payload.action) {
    throw new Error('Missing required field: action')
  }
  if (payload.action !== 'labeled') {
    throw new Error(`Unsupported action: ${payload.action}. Expected 'labeled'.`)
  }
  if (!payload.label?.name) {
    throw new Error('Missing required field: label.name')
  }
  if (payload.label.name !== 'bug') {
    throw new Error(`Label is not 'bug': ${payload.label.name}`)
  }
  if (!payload.issue?.title) {
    throw new Error('Missing required field: issue.title')
  }
  if (payload.issue.body === null || payload.issue.body === undefined) {
    throw new Error('Missing required field: issue.body')
  }

  const teamId = config.teamId ?? 'triage'
  const title = payload.issue.title
  const description = payload.issue.body

  const query = `
    mutation IssueCreate($input: IssueCreateInput!) {
      issueCreate(input: $input) {
        success
        issue {
          id
          identifier
          title
          description
        }
      }
    }
  `

  const variables = {
    input: {
      title,
      description,
      teamId,
    },
  }

  const result = await graphqlRequest(fetchImpl, config.linearApiKey, query, variables)

  const data = result as {
    data?: {
      issueCreate?: {
        success?: boolean
        issue?: {
          id?: string
          identifier?: string
        }
      }
    }
    errors?: Array<{ message: string }>
  }

  if (data.errors?.length) {
    throw new Error(`Linear GraphQL errors: ${data.errors.map(e => e.message).join(', ')}`)
  }

  const issueCreate = data.data?.issueCreate
  if (!issueCreate?.success || !issueCreate.issue?.id) {
    throw new Error('Linear issue creation failed: unexpected response shape')
  }

  return {
    linearIssueId: issueCreate.issue.id,
    linearIssueIdentifier: issueCreate.issue.identifier ?? '',
  }
}

