  SOURCE_EXAMPLE,
  TARGET_ENDPOINTS,
  contractFetch,
  fakeFetch,
  jsonResponse,
  RecordedCall,
} from './fixtures'

describe('contract', () => {
  it('handles the documented example payload', async () => {
    const { fetch, calls } = contractFetch()
    const config: ConnectorConfig = {
      linearApiKey: 'test-linear-key',
      teamId: 'triage',
      fetch,
    }
    const result = await handle(SOURCE_EXAMPLE as unknown as GitHubIssueLabelEvent, config)
    expect(calls.length).toBeGreaterThan(0)
    expect(result.linearIssueId).toBe('cml0ZXNzaW9uOnVzZXJfMTIz')
    expect(result.linearIssueIdentifier).toBe('TRI-123')
  })
})

