    const payload: GitHubIssueLabelEvent = {
      action: 'labeled',
      issue: {
        title: 'Fix login button alignment',
        body: 'The login button is misaligned on mobile devices. Need to adjust CSS.',
        labels: [{ name: 'bug' }, { name: 'frontend' }],
      },
      label: { name: 'bug' },
    }

    const result = await handle(payload, baseConfig)

    expect(calls.length).toBe(1)
    const call = calls[0]
    expect(call.method).toBe('POST')
