      action: 'labeled',
      issue: { title: 'Test', body: 'Body', labels: [{ name: 'bug' }] },
      label: { name: undefined },
    } as unknown as GitHubIssueLabelEvent

    await expect(handle(payload, baseConfig)).rejects.toThrow('Missing required field: label.name')
  })

