      action: 'labeled',
      issue: { title: 'Test', body: 'Body', labels: [{ name: 'feature' }] },
      label: { name: 'feature' },
    }

    await expect(handle(payload, baseConfig)).rejects.toThrow("Label is not 'bug': feature")
