      action: 'labeled',
      issue: { title: 'Test', body: undefined, labels: [{ name: 'bug' }] },
      label: { name: 'bug' },
    } as unknown as GitHubIssueLabelEvent

    await expect(handle(payload, baseConfig)).rejects.toThrow('Missing required field: issue.body')
